import { startForCapture } from './capture-start.mjs'
import captures from './wip-screenshots.cjs'
import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
captures.instrument({ chromium })
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const url = process.env.CAPTURE_URL, output = process.env.CAPTURE_DIR
if (!url || !output) throw new Error('Set CAPTURE_URL and CAPTURE_DIR.')
mkdirSync(output, { recursive: true })
const transient = error => { throw Object.assign(error, { exitCode: 75 }) }
let browser
try {
  browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 }).catch(transient)
  for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
    const page = await browser.newPage({ viewport: { width, height } }).catch(transient)
    page.setDefaultTimeout(30000)
    const failures = []
    page.on('pageerror', error => { console.error(error.message); failures.push(error.message) })
    page.on('response', response => { if (response.status() >= 400 && new URL(response.url()).origin === new URL(url).origin) failures.push(`HTTP ${response.status()}: ${response.url()}`) })
    const response = await page.goto(url, { waitUntil: 'load', timeout: 45000 }).catch(transient)
    if (!response?.ok()) throw Object.assign(new Error(`HTTP ${response?.status()} loading preview`), { exitCode: !response || [408, 429, 500, 502, 503, 504].includes(response.status()) ? 75 : 1 })
    await page.locator(process.env.CAPTURE_READY_SELECTOR || 'body').waitFor({ state: 'visible' })
    await page.waitForFunction(() => document.fonts.status === 'loaded')
    const start = await startForCapture(page, {
      enabled: process.env.CAPTURE_AUTO_START !== 'false',
      selector: process.env.CAPTURE_START_SELECTOR || ''
    })
    console.log(`Capture ${name}: auto-start ${start.clicked ? 'clicked' : start.reason}`)
    await page.waitForTimeout(1000)
    await page.screenshot({ path: join(output, `final-${name}.png`), timeout: 30000 }).catch(error => {
      if (error.name === 'TimeoutError' || !browser.isConnected()) transient(error)
      throw error
    })
    if (process.env.CAPTURE_STRICT === '1' && failures.length) throw new Error(`Published build failed: ${failures.join('; ')}`)
    await page.close()
  }
} catch (error) { console.error(error); process.exitCode = error.exitCode || 1 }
finally { await browser?.close().catch(error => { console.error(error); process.exitCode ||= 75 }) }
{
  "outputDir": "/home/runner/.local/share/omgithub-playwright/output",
  "browser": {
    "browserName": "chromium",
    "launchOptions": {
      "channel": "chromium",
      "headless": false,
      "args": ["--enable-gpu", "--ignore-gpu-blocklist", "--enable-unsafe-webgpu", "--use-angle=vulkan", "--enable-features=Vulkan", "--use-vulkan=swiftshader", "--use-webgpu-adapter=swiftshader", "--disable-vulkan-surface"]
    }
  }
}

// Start gameplay once without guessing between multiple controls or following links.
export async function startForCapture(page, { enabled = true, selector = '', timeout = 3000 } = {}) {
  if (!enabled) return { clicked: false, reason: 'disabled' }
  const candidate = selector
    ? page.locator(selector)
    : page.locator('button, input[type="button"], input[type="submit"], [role="button"]')
  const deadline = Date.now() + timeout
  do {
    const matches = []
    for (const control of await candidate.all()) {
      if (!await control.isVisible() || !await control.isEnabled()) continue
      const eligible = await control.evaluate((element, explicit) => {
        if (element.closest('a[href], form') || element.getAttribute('aria-disabled') === 'true') return false
        if (explicit) return true
        const label = element.getAttribute('aria-label') || element.value || element.textContent || ''
        return /^(?:start|play)(?:\s+(?:game|now))?$/i.test(label.trim())
      }, Boolean(selector))
      if (eligible) matches.push(control)
    }
    if (matches.length > 1) return { clicked: false, reason: 'ambiguous' }
    if (matches.length === 1) {
      try { await matches[0].click({ trial: true, timeout: 2000 }) }
      catch (error) {
        if (error.name === 'TimeoutError') return { clicked: false, reason: 'not-actionable' }
        throw error
      }
      await matches[0].click({ timeout: 2000, noWaitAfter: true })
      return { clicked: true }
    }
    if (Date.now() >= deadline) break
    await page.waitForTimeout(Math.min(200, Math.max(0, deadline - Date.now())))
  } while (Date.now() <= deadline)
  return { clicked: false, reason: 'not-found' }
}
const { createHash } = require('node:crypto')
const { mkdirSync, readFileSync, writeFileSync, existsSync, renameSync, appendFileSync } = require('node:fs')
const { join } = require('node:path')

function webDirectory(env) { return env.OMGITHUB_CAPTURE_WEB_DIR || env.OPENCODE_WEB_DIR }
// Controller-owned loopback ports never count as project pages: the OpenCode
// server default, and cloudflared's default metrics range. Runtime-allocated
// controller ports come from the workflow env and $OPENCODE_WEB_DIR/controller-ports.
const CONTROLLER_PORTS = [4096, 20241, 20242, 20243, 20244, 20245]
const CONTROLLER_PORT_ENV = ['OPENCODE_WEB_PORT', 'OPENCODE_CONTROL_PORT', 'PROJECT_FILE_PORT']
const LOOPBACK_HOSTS = new Set(['localhost', '127.0.0.1', '[::1]'])
function controllerPorts(env = process.env) {
  const ports = [...CONTROLLER_PORTS, ...CONTROLLER_PORT_ENV.map(name => env[name])]
  const directory = webDirectory(env)
  if (directory) try { ports.push(...readFileSync(join(directory, 'controller-ports'), 'utf8').split(/\s+/)) } catch {}
  return new Set(ports.map(Number).filter(port => Number.isSafeInteger(port) && port > 0))
}
function projectOrigins(env = process.env) {
  const directory = webDirectory(env)
  const port = env.APP_PORT || 3000
  const urls = [`http://localhost:${port}`, `http://127.0.0.1:${port}`, `http://[::1]:${port}`]
  if (env.APP_URL) urls.push(env.APP_URL)
  if (directory) {
    try { urls.push(readFileSync(join(directory, 'app-url'), 'utf8').trim()) } catch {}
    try { urls.push(...JSON.parse(readFileSync(join(directory, 'project-preview-origins.json'), 'utf8'))) } catch {}
  }
  return new Set(urls.flatMap(url => { try { return [new URL(url).origin] } catch { return [] } }))
}
// Returns '' for project pages, otherwise the skip reason.
function skipReason(url, env = process.env) {
  let parsed
  try { parsed = new URL(url) } catch { return 'invalid page URL' }
  if (!/^https?:$/.test(parsed.protocol)) return 'non-HTTP page'
  if (projectOrigins(env).has(parsed.origin)) return ''
  if (LOOPBACK_HOSTS.has(parsed.hostname)) {
    const port = Number(parsed.port || (parsed.protocol === 'https:' ? 443 : 80))
    return controllerPorts(env).has(port) ? 'controller port' : ''
  }
  return 'origin not a project preview'
}
function isProjectPage(url, env = process.env) { return !skipReason(url, env) }
function safeOrigin(url) { try { const parsed = new URL(url); return /^https?:$/.test(parsed.protocol) ? parsed.origin : parsed.protocol } catch { return 'invalid' } }
function logSkip(reason, url, env) {
  const line = `WIP screenshot skipped: ${reason} (${safeOrigin(url)})`
  console.error(line)
  const web = webDirectory(env)
  if (web) try { appendFileSync(join(web, 'wip-capture.log'), `${new Date().toISOString()} ${line}\n`) } catch {}
}
function imageType(bytes) {
  if (bytes.subarray(0, 8).toString('hex') === '89504e470d0a1a0a') return 'image/png'
  if (bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) return 'image/jpeg'
  if (bytes.subarray(0, 4).toString() === 'RIFF' && bytes.subarray(8, 12).toString() === 'WEBP') return 'image/webp'
  return ''
}
function queueScreenshot(bytes, metadata, env = process.env) {
  const web = webDirectory(env)
  if (!web) return null
  const reason = skipReason(metadata.page_url, env)
  if (reason) { logSkip(reason, metadata.page_url, env); return null }
  if (!Buffer.isBuffer(bytes) || !bytes.length || bytes.length > 10 * 1024 * 1024) { logSkip('empty or over 10 MB', metadata.page_url, env); return null }
  const type = imageType(bytes)
  if (!type) { logSkip('not PNG, JPEG, or WebP', metadata.page_url, env); return null }
  const hash = createHash('sha256').update(bytes).digest('hex'), dir = join(web, 'wip-queue')
  mkdirSync(dir, { recursive: true })
  if (existsSync(join(dir, `${hash}.json`)) || existsSync(join(dir, `${hash}.done`))) return hash
  const page = new URL(metadata.page_url); page.search = ''; page.hash = ''; page.username = ''; page.password = ''
  const value = { ...metadata, page_url: page.href, captured_at: metadata.captured_at || Date.now(), type, hash }
  try { writeFileSync(join(dir, `${hash}.image`), bytes, { flag: 'wx', mode: 0o600 }) } catch (error) { if (error.code !== 'EEXIST') throw error }
  const temporary = join(dir, `${hash}.${process.pid}.tmp`)
  writeFileSync(temporary, JSON.stringify(value), { mode: 0o600 })
  renameSync(temporary, join(dir, `${hash}.json`))
  return hash
}

// Keep agent screenshots small: CSS-pixel scale (no 2x/3x device pixels) and JPEG
// quality 70 when the caller asks for JPEG (type or .jpg/.jpeg path). PNG stays PNG so
// file names never lie about their bytes. OMGITHUB_SCREENSHOT_FULL=1 keeps full detail.
function shrinkOptions(options, env = process.env) {
  if (env.OMGITHUB_SCREENSHOT_FULL === '1') return options
  const value = { ...(options && typeof options === 'object' ? options : {}) }

